"""Shared helpers for the golden fixture pack (issue E0.8). Every file in this tree is synthetic.

Fixtures are read-only inputs. A test that needs to change one copies it first with `copy_to_tmp`.
Nothing dangerous or large is stored in Git: the EICAR test string is joined here from two encoded
halves, and oversize files are generated by `blob`.
"""

import base64
import shutil
import stat
import uuid
from pathlib import Path

FIXTURES_DIR = Path(__file__).resolve().parent
MAX_FILE_BYTES = 15 * 1024 * 1024  # upload limit per file (15 MB)
_BLOB_SEED = b"SBAM-FIXTURE-BLOB\n"


def fixture_path(*parts: str) -> Path:
    """Absolute path of a fixture, e.g. `fixture_path("documents", "text.pdf")`."""
    path = FIXTURES_DIR.joinpath(*parts)
    if not path.exists():
        raise FileNotFoundError(f"no such fixture: {'/'.join(parts)}")
    return path


def eicar_bytes() -> bytes:
    """The 68-byte EICAR antivirus test string, joined at call time from two stored halves.

    The plain string is never committed, and neither is it stored whole in any encoding: each half
    (`malware/eicar.part1.b64`, `eicar.part2.b64`) is the base64 of 34 bytes and decodes to a piece
    no scanner reports. One file holding the whole string, even encoded, was quarantined by Windows
    Defender on a developer machine (#202).
    """
    halves = [
        base64.b64decode(fixture_path("malware", name).read_text(encoding="ascii").strip())
        for name in ("eicar.part1.b64", "eicar.part2.b64")
    ]
    return b"".join(halves)


def blob(size: int) -> bytes:
    """Deterministic bytes of exactly `size` bytes, for size-boundary tests (e.g. 15 MB + 1)."""
    if size < 0:
        raise ValueError("size must not be negative")
    repeats, rest = divmod(size, len(_BLOB_SEED))
    return _BLOB_SEED * repeats + _BLOB_SEED[:rest]


def copy_to_tmp(*parts: str, tmp_path: Path) -> Path:
    """Copy a fixture into `tmp_path` and make the copy writable. The original is never touched."""
    target = tmp_path / parts[-1]
    shutil.copyfile(fixture_path(*parts), target)
    target.chmod(target.stat().st_mode | stat.S_IWUSR)
    return target


def document_version_uuid(relative: str) -> uuid.UUID:
    """Stable synthetic `document_version_id` for a fixture file, e.g. `"documents/text.pdf"`.

    SOW fixtures cite fixture documents by this UUID, so a test can map a citation back to its file.
    """
    return uuid.uuid5(uuid.NAMESPACE_URL, f"sbam-fixture:{relative}")
